script:
class CRMDeal {
	onLoad() {
		if (this.doc.__newDocument) return
		this.setActions()
	}
	setActions() {
		this.actions.push({
			label: __("Generate Service Quote"),
			onClick: () => {
				call(
					"ivm.client_portal.services.quote_generation.create_service_quote_from_deal",
					{ crm_deal: this.doc.name }
				).then((r) => {
					if (r && r.service_quote) {
						if (r.warning) toast.error(r.warning)
						window.open("/app/service-quote/" + r.service_quote, "_blank")
					} else {
						toast.error("Failed to create Service Quote")
					}
				}).catch((e) => {
					toast.error((e.messages && e.messages[0]) || "Error creating Service Quote")
				})
			}
		})
	}
	onRender() {
		if (this.doc.__newDocument) return
		this.renderDeploymentLocations()
	}
	renderDeploymentLocations() {
		call("ivm.deals.api.get_deployment_locations", { deal_name: this.doc.name })
			.then((sites) => {
				this.setFieldHtml("custom_locations_html", this.buildLocationsHtml(sites || []))
			})
			.catch(() => {
				this.setFieldHtml(
					"custom_locations_html",
					'<div class="text-ink-gray-4 text-sm py-2">Failed to load locations.</div>'
				)
			})
	}
	buildLocationsHtml(sites) {
		const deviceFields = [
			{ field: "number_of_machines", label: "SS" },
			{ field: "number_of_primary_lockers", label: "SL" },
			{ field: "number_of_secondary_lockers", label: "SSy" },
			{ field: "number_of_vaults", label: "SV" },
			{ field: "number_of_kiosks", label: "SC" },
		]
		const escape = (v) =>
			String(v == null ? "" : v).replace(/[&<>"']/g, (c) => ({
				"&": "&amp;",
				"<": "&lt;",
				">": "&gt;",
				'"': "&quot;",
				"'": "&#39;",
			}[c]))

		const totals = deviceFields.map(({ field, label }) => ({
			label,
			count: sites.reduce((sum, s) => sum + (s[field] || 0), 0),
		}))

		const totalsHtml = `
			<div class="flex justify-between px-1 pb-3">
				${totals.map(({ label, count }) => `
					<div class="flex flex-col items-center">
						<div class="text-xs text-ink-gray-5">${label}</div>
						<div class="text-sm font-medium text-ink-gray-8">${count}</div>
					</div>
				`).join("")}
			</div>
		`

		let listHtml
		if (!sites.length) {
			listHtml = '<div class="text-ink-gray-4 text-sm py-2">No sites yet.</div>'
		} else {
			listHtml = sites.map((site) => `
				<a href="/app/deployment-location/${encodeURIComponent(site.name)}"
				   class="flex flex-col gap-0.5 px-2 py-2 border-b border-outline-gray-modals hover:bg-surface-gray-2 no-underline text-ink-gray-8">
					<div class="flex items-center justify-between">
						<span class="text-sm font-medium">${escape(site.location_name || site.name)}</span>
						<span class="text-xs text-ink-gray-5">${escape(site.locale || "")}</span>
					</div>
					<div class="flex gap-3 text-xs text-ink-gray-5">
						<span>SS ${site.number_of_machines || 0}</span>
						<span>SL ${site.number_of_primary_lockers || 0}</span>
						<span>SSy ${site.number_of_secondary_lockers || 0}</span>
						<span>SV ${site.number_of_vaults || 0}</span>
						<span>SC ${site.number_of_kiosks || 0}</span>
					</div>
				</a>
			`).join("")
		}

		const addHref = `/app/deployment-location/new?crm_deal=${encodeURIComponent(this.doc.name)}`

		return `
			<div class="flex flex-col">
				${totalsHtml}
				<div class="flex flex-col">${listHtml}</div>
				<a href="${addHref}" class="text-sm text-ink-blue-link font-medium py-2 px-1 no-underline">+ Add Site</a>
			</div>
		`
	}
}
